def read_existing_content_hash(doc_abs_path: Path) -> str | None:
    """Extract `sources[0].content_hash` from an existing OKF doc's frontmatter, if any."""
    if not doc_abs_path.is_file():
        return None
    try:
        text = doc_abs_path.read_text(encoding="utf-8")
    except OSError:
        return None

    match = _FRONTMATTER_RE.match(text)
    frontmatter = match.group(1) if match else text
    hash_match = _CONTENT_HASH_RE.search(frontmatter)
    return hash_match.group(1) if hash_match else None

def topological_doc_order(graph: CodeGraph) -> list[GraphNode]:
    """Return clusterable nodes ordered so every callee/base precedes its callers.

    Cycles (mutual/recursive calls) can't be strictly ordered; nodes involved
    in a cycle are appended in a stable (id-sorted) order once every node
    outside the cycle that can be resolved has been. This never raises on
    cyclic graphs — RepoAgent's own DAG assumption doesn't hold for real
    codebases with recursion, so we degrade gracefully instead of crashing.
    """
    nodes = {n.id: n for n in graph.nodes.values() if n.kind in _CLUSTERABLE_KINDS}
    if not nodes:
        return []

    # dependency edges: source depends on target (target must be documented first)
    depends_on: dict[str, set[str]] = {node_id: set() for node_id in nodes}
    dependents: dict[str, set[str]] = {node_id: set() for node_id in nodes}
    for edge in graph.edges:
        if edge.kind not in _ORDER_EDGE_KINDS:
            continue
        if edge.source not in nodes or edge.target not in nodes:
            continue
        if edge.source == edge.target:
            continue
        depends_on[edge.source].add(edge.target)
        dependents[edge.target].add(edge.source)

    remaining_deps = {node_id: set(deps) for node_id, deps in depends_on.items()}
    ready = sorted(node_id for node_id, deps in remaining_deps.items() if not deps)
    ordered: list[str] = []
    seen: set[str] = set()

    while ready:
        ready.sort()
        node_id = ready.pop(0)
        if node_id in seen:
            continue
        seen.add(node_id)
        ordered.append(node_id)
        for dependent in sorted(dependents.get(node_id, ())):
            if dependent in seen:
                continue
            remaining_deps[dependent].discard(node_id)
            if not remaining_deps[dependent]:
                ready.append(dependent)

    # Anything left is part of a cycle; append deterministically.
    leftover = sorted(node_id for node_id in nodes if node_id not in seen)
    ordered.extend(leftover)

    return [nodes[node_id] for node_id in ordered]

def _add_directory_nodes(ctx: BuildContext, walk_result: WalkResult) -> None:
    for dir_rel in sorted(walk_result.directories):
        parent_rel = Path(dir_rel).parent.as_posix()
        parent_id = dir_node_id(parent_rel) if parent_rel != "." else None
        node = ctx.graph.add_node(
            GraphNode(
                id=dir_node_id(dir_rel),
                kind=DIRECTORY,
                name=Path(dir_rel).name,
                qualified_name=dir_rel,
                parent_id=parent_id,
            )
        )
        if parent_id:
            ctx.graph.add_edge(GraphEdge(source=parent_id, target=node.id, kind=CONTAINS))

def _make_snippet(source: bytes, start_byte: int, end_byte: int) -> str:
    text = source[start_byte:end_byte].decode("utf-8", errors="replace")
    if len(text) > _SNIPPET_MAX_CHARS:
        return text[:_SNIPPET_MAX_CHARS] + "\n… (truncated)"
    return text

def assign_communities(graph: CodeGraph) -> int:
    """Assign `community_id` to class/function/method nodes in place.

    Returns the number of distinct communities found, or 0 if clustering was
    skipped (igraph unavailable, or fewer than 2 clusterable nodes).
    """
    try:
        import igraph as ig  # type: ignore[import-untyped]
    except ImportError:
        return 0

    node_ids = [n.id for n in graph.nodes.values() if n.kind in _CLUSTERABLE_KINDS]
    if len(node_ids) < 2:
        return 0

    index = {node_id: i for i, node_id in enumerate(node_ids)}
    node_set = set(node_ids)

    edges: list[tuple[int, int]] = []
    weights: list[float] = []
    for edge in graph.edges:
        weight = _EDGE_WEIGHTS.get(edge.kind)
        if weight is None:
            continue
        if edge.source not in node_set or edge.target not in node_set:
            continue
        edges.append((index[edge.source], index[edge.target]))
        weights.append(weight)

    g = ig.Graph(n=len(node_ids), directed=True)
    if edges:
        g.add_edges(edges)
        g.es["weight"] = weights

    partition = g.community_leiden(
        objective_function="modularity",
        weights="weight" if edges else None,
    )

    for node_id, community_id in zip(node_ids, partition.membership, strict=True):
        graph.nodes[node_id].community_id = community_id

    return len(set(partition.membership))

def _clean_import_text(text: str) -> str:
    text = text.strip()
    if len(text) >= 2 and text[0] in "\"'" and text[-1] == text[0]:
        text = text[1:-1]
    return text

def run_pipeline(root: Path, max_file_size: int = 2_000_000) -> PipelineResult:
    """Walk `root`, build the code graph, resolve edges, and cluster it."""
    lang_status = available_languages()
    avail = {lang for lang, err in lang_status.items() if err is None}
    language_warnings = {lang: err for lang, err in lang_status.items() if err is not None}

    walk_result = walk(root, max_file_size=max_file_size, available_languages=avail)

    build_ctx = build_graph(walk_result)
    resolve(build_ctx)
    community_count = assign_communities(build_ctx.graph)

    return PipelineResult(
        root=root,
        walk_result=walk_result,
        build_ctx=build_ctx,
        community_count=community_count,
        language_warnings=language_warnings,
    )

def _candidate_exists(file_paths: set[str | None], *candidates: str) -> str | None:
    for c in candidates:
        if c in file_paths:
            return c
    return None

def _resolve_call(
    ctx: BuildContext,
    call: PendingCall,
    class_methods: dict[str, dict[str, str]],
) -> None:
    target_id: str | None = None

    if call.receiver in _SELF_RECEIVERS and call.enclosing_class_id:
        target_id = class_methods.get(call.enclosing_class_id, {}).get(call.call_name)

    if target_id is None and call.receiver is None:
        symbol_index = ctx.file_symbol_index.get(call.importing_file_rel, {})
        candidate = symbol_index.get(call.call_name)
        if candidate is not None:
            node = ctx.graph.nodes.get(candidate)
            if node is not None and node.kind in (FUNCTION, METHOD, CLASS):
                target_id = candidate

    if target_id is not None:
        edge = GraphEdge(source=call.source_id, target=target_id, kind=CALLS, resolved=True)
    else:
        external_name = f"{call.receiver}.{call.call_name}" if call.receiver else call.call_name
        external = ctx.graph.get_or_create_external(external_name)
        edge = GraphEdge(source=call.source_id, target=external.id, kind=CALLS, resolved=False)
    ctx.graph.add_edge(edge)

def _resolve_js_import(imp: PendingImport, file_paths: set[str | None]) -> str | None:
    text = imp.path_text
    if not text.startswith("."):
        return None
    importing_dir = PurePosixPath(imp.importing_file_rel).parent
    base = (importing_dir / text).as_posix()
    base = str(PurePosixPath(base))

    candidates = [base] if PurePosixPath(base).suffix else []
    for suffix in _JS_SUFFIXES:
        candidates.append(f"{base}{suffix}")
    for suffix in _JS_SUFFIXES:
        candidates.append(f"{base}/index{suffix}")

    return _candidate_exists(file_paths, *candidates)

def _resolve_python_import(imp: PendingImport, file_paths: set[str | None]) -> str | None:
    text = imp.path_text
    importing_dir = PurePosixPath(imp.importing_file_rel).parent

    if text.startswith("."):
        dots = len(text) - len(text.lstrip("."))
        remainder = text[dots:]
        base = importing_dir
        for _ in range(dots - 1):
            base = base.parent
        module_path = base / remainder.replace(".", "/") if remainder else base
    else:
        module_path = PurePosixPath(text.replace(".", "/"))

    return _candidate_exists(
        file_paths,
        f"{module_path}.py",
        f"{module_path}/__init__.py",
    )

def _resolve_rust_import(imp: PendingImport, file_paths: set[str | None]) -> str | None:
    text = imp.path_text
    importing_dir = PurePosixPath(imp.importing_file_rel).parent

    if text.startswith("crate::") or text == "crate":
        remainder = text[len("crate::") :] if text != "crate" else ""
        base = PurePosixPath("src") / remainder.replace("::", "/") if remainder else PurePosixPath("src/lib")
    elif text.startswith("self::"):
        remainder = text[len("self::") :]
        base = importing_dir / remainder.replace("::", "/")
    elif text.startswith("super::"):
        remainder = text[len("super::") :]
        base = importing_dir.parent / remainder.replace("::", "/")
    else:
        return None

    return _candidate_exists(file_paths, f"{base}.rs", f"{base}/mod.rs")

def _resolve_import(ctx: BuildContext, imp: PendingImport, file_paths: set[str | None]) -> None:
    target_rel: str | None = None

    if imp.language == "python":
        target_rel = _resolve_python_import(imp, file_paths)
    elif imp.language in ("javascript", "typescript", "tsx"):
        target_rel = _resolve_js_import(imp, file_paths)
    elif imp.language == "rust":
        target_rel = _resolve_rust_import(imp, file_paths)
    elif imp.language in ("java", "kotlin"):
        target_rel = _resolve_dotted_suffix_import(imp, file_paths)
    # go, csharp, swift: left external in this MVP (see module docstring)

    if target_rel is not None:
        edge = GraphEdge(source=imp.source_id, target=f"file:{target_rel}", kind=IMPORTS, resolved=True)
    else:
        external = ctx.graph.get_or_create_external(imp.path_text)
        edge = GraphEdge(source=imp.source_id, target=external.id, kind=IMPORTS, resolved=False)
    ctx.graph.add_edge(edge)

def resolve(ctx: BuildContext) -> None:
    file_paths = {node.file_path for node in ctx.graph.nodes.values() if node.kind == FILE}
    class_methods: dict[str, dict[str, str]] = {}
    for node in ctx.graph.nodes.values():
        if node.kind == METHOD and node.parent_id:
            class_methods.setdefault(node.parent_id, {})[node.name] = node.id

    for imp in ctx.pending_imports:
        _resolve_import(ctx, imp, file_paths)

    for call in ctx.pending_calls:
        _resolve_call(ctx, call, class_methods)

def _load_spec(lang_id: str) -> LanguageSpec:
    if lang_id not in _GRAMMAR_SOURCES:
        raise ValueError(f"Unknown language id: {lang_id}")

    module_name, attr_name = _GRAMMAR_SOURCES[lang_id]
    module = importlib.import_module(module_name)
    getter = getattr(module, attr_name)
    language = ts.Language(getter())

    query_filename = _QUERY_FILES[lang_id]
    query_text = (
        importlib.resources.files(QUERIES_PACKAGE).joinpath(query_filename).read_text(encoding="utf-8")
    )
    query = ts.Query(language, query_text)

    return LanguageSpec(id=lang_id, language=language, query=query)

def available_languages() -> dict[str, str | None]:
    """Return {language_id: None} for loadable languages, {language_id: error} otherwise."""
    result: dict[str, str | None] = {}
    for lang_id in _GRAMMAR_SOURCES:
        try:
            _load_spec(lang_id)
            result[lang_id] = None
        except Exception as exc:  # noqa: BLE001 - want to record any load failure
            result[lang_id] = str(exc)
    return result

def get_spec(lang_id: str) -> LanguageSpec | None:
    """Return the LanguageSpec for lang_id, or None if unavailable (missing grammar/query)."""
    try:
        return _load_spec(lang_id)
    except Exception:  # noqa: BLE001
        return None

