def _native_grep_search(query: str) -> str:
    """Fuzzy/regex search files recursively in the workspace as a fallback."""
    matches: list[str] = []
    p = Path(".")
    try:
        pattern = re.compile(query, re.IGNORECASE)
    except Exception:
        pattern = re.compile(re.escape(query), re.IGNORECASE)

    try:
        for path in p.rglob("*"):
            if path.is_file():
                parts = path.parts
                if not any(
                    ignored in parts
                    for ignored in (
                        ".git",
                        "node_modules",
                        ".buddhi",
                        ".venv",
                        "venv",
                        ".agents",
                        "__pycache__",
                    )
                ):
                    try:
                        with path.open("r", encoding="utf-8", errors="replace") as f:
                            for idx, line in enumerate(f, 1):
                                if pattern.search(line):
                                    matches.append(f"{path.as_posix()}:{idx}: {line.strip()}")
                                    if len(matches) >= 50:
                                        break
                    except Exception:
                        pass
            if len(matches) >= 50:
                break
    except Exception:
        pass

    if matches:
        return "### [fallback: native grep] Native Grep Fallback Matches:\n" + "\n".join(matches)
    return ""

def extract_signature(content: str, signature: str, node_type: str) -> str:
    """Extract or return signature and docstring from definition."""
    if signature and signature.strip():
        return signature.strip()

    if not content:
        return content

    lines = content.splitlines()
    nt = node_type.lower()
    if "function" in nt or "method" in nt or "class" in nt:
        sig_lines: list[str] = []
        found_colon = False
        for line in lines:
            sig_lines.append(line)
            if not found_colon and (line.rstrip().endswith(":") or line.rstrip().endswith("{")):
                found_colon = True
                continue
            if found_colon:
                stripped = line.strip()
                if stripped.startswith('"""') or stripped.startswith("'''") or stripped.startswith("/*"):
                    sig_lines.append(line)
                    if (
                        stripped.count('"""') >= 2
                        or stripped.count("'''") >= 2
                        or "*/" in stripped
                    ):
                        break
                    for remaining in lines[len(sig_lines) :]:
                        sig_lines.append(remaining)
                        if '"""' in remaining or "'''" in remaining or "*/" in remaining:
                            break
                break

        if sig_lines:
            return "\n".join(sig_lines)

    return lines[0] if lines else content

def filter_low_entropy_lines(content: str, threshold: float = _ENTROPY_THRESHOLD) -> str:
    """Remove lines with Shannon entropy below the threshold."""
    if not content:
        return content

    lines = content.splitlines()
    filtered: list[str] = []

    for line in lines:
        stripped = line.strip()
        if not stripped or len(stripped) < 10:
            filtered.append(line)
            continue

        entropy = calculate_entropy(stripped)
        if entropy >= threshold:
            filtered.append(line)

    return "\n".join(filtered)

def render_content(result: SearchResult) -> str:
    """Render node content according to its current mode."""
    if result.mode == "map":
        return extract_map_entry(result)

    if result.mode == "signatures":
        content = extract_signature(result.content, result.signature, result.node_type)
    else:
        content = result.content or result.signature

    return filter_low_entropy_lines(content)

def serialize_context(nodes: list[SearchResult]) -> str:
    """Serialize search results into delimited text with boundary markers."""
    if not nodes:
        return ""

    blocks: list[str] = []
    for result in nodes:
        header = f"--- START SYMBOL: {result.file_path}::{result.name} (L{result.start_line}-L{result.end_line}) ---"
        content = render_content(result)
        footer = "--- END SYMBOL ---"
        blocks.append(f"{header}\n{content}\n{footer}")

    return "\n\n".join(blocks)

def atomic_write_bytes(path: Path, data: bytes) -> None:
    tmp_path = path.with_name(f"{path.name}.tmp-{os.getpid()}")
    try:
        tmp_path.write_bytes(data)
        os.replace(tmp_path, path)
    except BaseException:
        tmp_path.unlink(missing_ok=True)
        raise

def _community_color(community_id: int) -> dict[str, str]:
    hue = (community_id * 0.618033988749895) % 1.0
    r, g, b = colorsys.hsv_to_rgb(hue, 0.6, 0.9)
    background = f"#{int(r * 255):02x}{int(g * 255):02x}{int(b * 255):02x}"
    return {"background": background, "border": "#f8fafc"}

def _legend_html() -> str:
    return "".join(
        _LEGEND_ITEM.format(color=_KIND_COLORS[kind]["background"], label=label, kind=kind)
        for kind, label in _KIND_LABELS
    )

def _node_color(kind: str, community_id: int | None) -> dict[str, str]:
    if kind in _CLUSTERABLE_KINDS and community_id is not None:
        return _community_color(community_id)
    return _KIND_COLORS.get(kind, {"background": "#3b82f6", "border": "#60a5fa"})

def _build_vis_data(graph: CodeGraph) -> dict:
    nodes = []
    for node in graph.nodes.values():
        color = _node_color(node.kind, node.community_id)
        nodes.append(
            {
                "id": node.id,
                "label": node.name,
                "kind": node.kind,
                "qualified_name": node.qualified_name,
                "file_path": node.file_path,
                "start_line": node.start_line,
                "end_line": node.end_line,
                "snippet": node.snippet,
                "community_id": node.community_id,
                "color": {
                    "background": color["background"],
                    "border": color["border"],
                    "highlight": {"background": color["background"], "border": "#f8fafc"},
                    "hover": {"background": color["background"], "border": "#f8fafc"},
                },
            }
        )

    edges = []
    for edge in graph.edges:
        if edge.kind == CONTAINS:
            continue
        edges.append(
            {
                "from": edge.source,
                "to": edge.target,
                "kind": edge.kind,
                "color": {"color": _EDGE_COLORS.get(edge.kind, "#64748b"), "opacity": 0.5},
            }
        )

    return {"nodes": nodes, "edges": edges}

def to_cytoscape_elements(graph: CodeGraph) -> dict:
    nodes = []
    for node in graph.nodes.values():
        data = {
            "id": node.id,
            "label": node.name,
            "kind": node.kind,
            "qualified_name": node.qualified_name,
            "file_path": node.file_path,
            "language": node.language,
            "start_line": node.start_line,
            "end_line": node.end_line,
            "external": node.external,
            "snippet": node.snippet,
            "community_id": node.community_id,
        }
        if node.parent_id:
            data["parent"] = node.parent_id
        nodes.append({"data": data})

    edges = []
    for i, edge in enumerate(graph.edges):
        edges.append(
            {
                "data": {
                    "id": f"e{i}",
                    "source": edge.source,
                    "target": edge.target,
                    "kind": edge.kind,
                    "resolved": edge.resolved,
                }
            }
        )

    return {"nodes": nodes, "edges": edges}

def _dir_has_entries(path: Path) -> bool:
    try:
        return path.is_dir() and any(path.iterdir())
    except OSError:
        return False

def _available_docs(paths: FeaturePaths, include_tasks: bool) -> list[str]:
    docs: list[str] = []
    if paths.research.is_file():
        docs.append("research.md")
    if paths.data_model.is_file():
        docs.append("data-model.md")
    if _dir_has_entries(paths.contracts_dir):
        docs.append("contracts/")
    if paths.quickstart.is_file():
        docs.append("quickstart.md")
    if include_tasks and paths.tasks.is_file():
        docs.append("tasks.md")
    return docs

def _parse_args(argv: list[str]) -> Args:
    json_mode = False
    require_tasks = False
    include_tasks = False
    paths_only = False
    template_name = None

    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg == "--json":
            json_mode = True
        elif arg == "--require-tasks":
            require_tasks = True
        elif arg == "--include-tasks":
            include_tasks = True
        elif arg == "--paths-only":
            paths_only = True
        elif arg == "--template":
            index += 1
            if index >= len(argv):
                print(
                    "ERROR: --template requires a template name",
                    file=sys.stderr,
                )
                raise SystemExit(1)
            template_name = argv[index]
        elif arg in {"--help", "-h"}:
            sys.stdout.write(HELP_TEXT)
            raise SystemExit(0)
        else:
            print(
                f"ERROR: Unknown option '{arg}'. Use --help for usage information.",
                file=sys.stderr,
            )
            raise SystemExit(1)
        index += 1

    return Args(
        json_mode=json_mode,
        require_tasks=require_tasks,
        include_tasks=include_tasks,
        paths_only=paths_only,
        template_name=template_name,
    )

def _status_marker(ok: bool) -> str:
    glyph = "✓" if ok else "✗"
    try:
        glyph.encode(getattr(sys.stdout, "encoding", None) or "utf-8")
    except (LookupError, UnicodeEncodeError):
        return "[OK]" if ok else "[FAIL]"
    return glyph

def main(argv: list[str] | None = None) -> int:
    args = _parse_args(list(argv if argv is not None else sys.argv[1:]))

    try:
        paths = get_feature_paths(
            no_persist=args.paths_only,
            script_file=Path(__file__),
        )
    except SystemExit as exc:
        if exc.code == 0:
            return 0
        print("ERROR: Failed to resolve feature paths", file=sys.stderr)
        return int(exc.code) if isinstance(exc.code, int) else 1

    if args.paths_only:
        _print_paths_only(paths, args.json_mode)
        return 0

    if not paths.feature_dir.is_dir():
        print(f"ERROR: Feature directory not found: {paths.feature_dir}", file=sys.stderr)
        print(
            f"Run {format_speckit_command('specify', paths.repo_root)} first to create the feature structure.",
            file=sys.stderr,
        )
        return 1

    if not paths.impl_plan.is_file():
        print(f"ERROR: plan.md not found in {paths.feature_dir}", file=sys.stderr)
        print(
            f"Run {format_speckit_command('plan', paths.repo_root)} first to create the implementation plan.",
            file=sys.stderr,
        )
        return 1

    if args.require_tasks and not paths.tasks.is_file():
        print(f"ERROR: tasks.md not found in {paths.feature_dir}", file=sys.stderr)
        print(
            f"Run {format_speckit_command('tasks', paths.repo_root)} first to create the task list.",
            file=sys.stderr,
        )
        return 1

    docs = _available_docs(paths, args.include_tasks)
    template_content = None
    if args.template_name:
        try:
            template_content = resolve_template_content(
                args.template_name, paths.repo_root
            )
        except TemplateResolutionError as exc:
            print(f"ERROR: {exc}", file=sys.stderr)
            return 1
        if template_content is None:
            print(
                f"ERROR: Could not resolve required {args.template_name} from template stack",
                file=sys.stderr,
            )
            return 1

    if args.json_mode:
        payload: dict[str, object] = {
            "FEATURE_DIR": str(paths.feature_dir),
            "AVAILABLE_DOCS": docs,
        }
        if args.template_name:
            payload["TEMPLATE_CONTENT"] = template_content
        sys.stdout.write(_json_line(payload))
    else:
        _print_text_results(paths, args.include_tasks)
    return 0

def _conventional_template(
    base_dir: Path, template_name: str
) -> Path | None:
    for candidate in (
        base_dir / "templates" / f"{template_name}.md",
        base_dir / f"{template_name}.md",
    ):
        if candidate.is_file():
            return candidate
    return None

def _get_bundled_template_content(template_name: str) -> str | None:
    try:
        template_file = resources.files("buddhi.templates.agents.templates") / f"{template_name}.md"
        if template_file.is_file():
            return template_file.read_text(encoding="utf-8")
    except (OSError, UnicodeError, AttributeError, ModuleNotFoundError, TypeError):
        pass
    return None

def _is_safe_component(value: object) -> bool:
    return (
        isinstance(value, str)
        and _SAFE_COMPONENT_PATTERN.fullmatch(value) is not None
    )

def _normalize_priority(value: object) -> int:
    if isinstance(value, bool):
        return 10
    if isinstance(value, (int, str)):
        try:
            priority = int(value)
            return priority if priority >= 1 else 10
        except (TypeError, ValueError, OverflowError):
            return 10
    return 10

def _trim_trailing_separators(value: Path) -> str:
    text = str(value)
    while len(text) > 1 and text.endswith((os.sep, "/")):
        text = text[:-1]
    return text

def find_buddhi_root(start_dir: Path | None = None) -> Path | None:
    current = (start_dir or Path.cwd()).resolve()
    while True:
        if (current / ".buddhi").is_dir() or (current / ".agents").is_dir() or (current / ".specify").is_dir():
            return current
        parent = current.parent
        if parent == current:
            return None
        current = parent

def format_speckit_command(command_name: str, repo_root: Path | None = None) -> str:
    name = command_name.lstrip("/")
    if name.startswith("speckit."):
        name = name[len("speckit.") :]
    elif name.startswith("speckit-"):
        name = name[len("speckit-") :]
    elif name.startswith("sdd-"):
        name = name[len("sdd-") :]
    return f"/{name}"

def get_current_branch() -> str:
    env_branch = os.environ.get("SPECIFY_FEATURE", "")
    if env_branch:
        return env_branch
    try:
        res = subprocess.run(
            ["git", "branch", "--show-current"],
            capture_output=True,
            text=True,
            check=False,
        )
        if res.returncode == 0 and res.stdout.strip():
            return res.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        pass
    return ""

def read_feature_json_feature_directory(repo_root: Path) -> str:
    for candidate in [
        repo_root / ".buddhi" / "feature.json",
        repo_root / ".specify" / "feature.json",
    ]:
        if candidate.is_file():
            try:
                data = json.loads(candidate.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    val = data.get("feature_directory")
                    if isinstance(val, str) and val.strip():
                        return val.strip()
            except (OSError, UnicodeError, json.JSONDecodeError):
                pass
    return ""

def persist_feature_json(repo_root: Path, feature_dir_value: str) -> None:
    value = feature_dir_value
    relative = Path(value)
    if relative.is_absolute():
        try:
            value = relative.relative_to(repo_root).as_posix()
        except ValueError:
            value = str(relative)

    current = read_feature_json_feature_directory(repo_root)
    if current == value:
        return

    buddhi_dir = repo_root / ".buddhi"
    buddhi_dir.mkdir(parents=True, exist_ok=True)
    (buddhi_dir / "feature.json").write_bytes(
        _json_dump({"feature_directory": value}).encode("utf-8")
    )

def resolve_specify_init_dir() -> Path:
    raw = os.environ.get("SPECIFY_INIT_DIR", "")
    candidate = Path(raw)
    if not candidate.is_absolute():
        candidate = Path.cwd() / candidate
    try:
        init_root = candidate.resolve(strict=True)
    except OSError:
        print(
            f"ERROR: SPECIFY_INIT_DIR does not point to an existing directory: {raw}",
            file=sys.stderr,
        )
        raise SystemExit(1)
    if not init_root.is_dir():
        print(
            f"ERROR: SPECIFY_INIT_DIR does not point to an existing directory: {raw}",
            file=sys.stderr,
        )
        raise SystemExit(1)
    return init_root

def get_repo_root(script_file: Path | None = None) -> Path:
    if os.environ.get("SPECIFY_INIT_DIR"):
        return resolve_specify_init_dir()

    root = find_buddhi_root()
    if root is not None:
        return root

    if script_file is not None:
        script_root = find_buddhi_root(script_file.resolve().parent)
        if script_root is not None:
            return script_root

    return Path.cwd().resolve()

def get_feature_paths(
    *, no_persist: bool = False, script_file: Path | None = None
) -> FeaturePaths:
    repo_root = get_repo_root(script_file)
    current_branch = get_current_branch()

    feature_dir_raw = os.environ.get("SPECIFY_FEATURE_DIRECTORY", "")
    if feature_dir_raw:
        feature_dir = Path(feature_dir_raw)
        if not feature_dir.is_absolute():
            feature_dir = repo_root / feature_dir
        if not no_persist:
            persist_feature_json(repo_root, feature_dir_raw)
    else:
        stored = read_feature_json_feature_directory(repo_root)
        if stored:
            feature_dir = Path(stored)
            if not feature_dir.is_absolute():
                feature_dir = repo_root / feature_dir
        elif current_branch:
            # Check if .buddhi/specs/<branch> or specs/<branch> exists
            buddhi_spec_dir = repo_root / ".buddhi" / "specs" / current_branch
            root_spec_dir = repo_root / "specs" / current_branch
            if buddhi_spec_dir.is_dir():
                feature_dir = buddhi_spec_dir
            elif root_spec_dir.is_dir():
                feature_dir = root_spec_dir
            else:
                feature_dir = buddhi_spec_dir
        else:
            print(
                "ERROR: Feature directory not found. Set SPECIFY_FEATURE_DIRECTORY "
                "or run the /specify command to create .buddhi/specs/<feature>.",
                file=sys.stderr,
            )
            raise SystemExit(1)

    if not current_branch:
        current_branch = Path(_trim_trailing_separators(feature_dir)).name

    return FeaturePaths(
        repo_root=repo_root,
        current_branch=current_branch,
        feature_dir=feature_dir,
        feature_spec=feature_dir / "spec.md",
        impl_plan=feature_dir / "plan.md",
        tasks=feature_dir / "tasks.md",
        research=feature_dir / "research.md",
        data_model=feature_dir / "data-model.md",
        quickstart=feature_dir / "quickstart.md",
        contracts_dir=feature_dir / "contracts",
    )

def resolve_template_content(template_name: str, repo_root: Path) -> str | None:
    """Resolve and compose template content through the project layer stack."""
    if not _is_safe_component(template_name):
        return None

    # 1. Project overrides and templates under .agents/templates/
    agents_templates = repo_root / ".agents" / "templates"
    override = agents_templates / "overrides" / f"{template_name}.md"
    if override.is_file():
        try:
            return override.read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(f"Failed to read {override}: {exc}") from exc

    core = agents_templates / f"{template_name}.md"
    if core.is_file():
        try:
            return core.read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(f"Failed to read {core}: {exc}") from exc

    # 2. Legacy .specify/templates/
    specify_templates = repo_root / ".specify" / "templates"
    specify_override = specify_templates / "overrides" / f"{template_name}.md"
    if specify_override.is_file():
        try:
            return specify_override.read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(f"Failed to read {specify_override}: {exc}") from exc

    specify_core = specify_templates / f"{template_name}.md"
    if specify_core.is_file():
        try:
            return specify_core.read_bytes().decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise TemplateResolutionError(f"Failed to read {specify_core}: {exc}") from exc

    # 3. Built-in bundled template fallback
    bundled = _get_bundled_template_content(template_name)
    if bundled is not None:
        return bundled

    return None

def _clean_branch_name(name: str) -> str:
    cleaned = re.sub(r"[^a-z0-9]", "-", name.lower())
    cleaned = re.sub(r"-+", "-", cleaned)
    return cleaned.strip("-")

def _generate_branch_name(description: str) -> str:
    clean = re.sub(r"[^a-z0-9]", " ", description.lower())
    meaningful: list[str] = []
    for word in clean.split():
        if word in _STOP_WORDS:
            continue
        if len(word) >= 3 or re.search(
            rf"(?<![0-9A-Za-z_]){re.escape(word.upper())}(?![0-9A-Za-z_])",
            description,
        ):
            meaningful.append(word)

    if meaningful:
        max_words = 4 if len(meaningful) == 4 else 3
        return "-".join(meaningful[:max_words])

    cleaned = _clean_branch_name(description)
    return "-".join([part for part in cleaned.split("-") if part][:3])

def _int64_from_digits(value: str) -> int | None:
    normalized = value.lstrip("0") or "0"
    maximum = str(_MAX_FEATURE_NUMBER)
    if len(normalized) > len(maximum) or (
        len(normalized) == len(maximum) and normalized > maximum
    ):
        return None
    return int(normalized, 10)

def _get_highest_from_specs(specs_dir: Path) -> int:
    highest = 0
    if not specs_dir.is_dir():
        return highest
    for entry in specs_dir.iterdir():
        if not entry.is_dir():
            continue
        name = entry.name
        if re.match(r"^[0-9]{3,}-", name) and not re.match(
            r"^[0-9]{8}-[0-9]{6}-", name
        ):
            m = re.match(r"^[0-9]+", name)
            if m is not None:
                number = _int64_from_digits(m.group())
                if number is not None:
                    highest = max(highest, number)
    return highest

def _persistence_assignments(
    branch_name: str, feature_dir: str, *, powershell: bool
) -> tuple[str, str]:
    if powershell:
        quoted_branch = "'" + branch_name.replace("'", "''") + "'"
        quoted_dir = "'" + feature_dir.replace("'", "''") + "'"
        return (
            f"$env:SPECIFY_FEATURE = {quoted_branch}",
            f"$env:SPECIFY_FEATURE_DIRECTORY = {quoted_dir}",
        )
    return (
        f"export SPECIFY_FEATURE={shlex.quote(branch_name)}",
        f"export SPECIFY_FEATURE_DIRECTORY={shlex.quote(feature_dir)}",
    )

def _spec_prefix_exists(specs_dir: Path, feature_num: str) -> bool:
    try:
        return any(
            entry.is_dir() and entry.name.startswith(f"{feature_num}-")
            for entry in specs_dir.iterdir()
        )
    except OSError:
        return False

def _has_spec_prefix_conflict(
    specs_dir: Path,
    feature_num: str,
    requested_dir: Path,
    *,
    allow_existing: bool,
) -> bool:
    if allow_existing and requested_dir.is_dir():
        return False

    return _spec_prefix_exists(specs_dir, feature_num)

def _usage(argv0: str) -> str:
    return (
        f"Usage: {argv0} [--json] [--dry-run] [--allow-existing-branch] "
        "[--short-name <name>] [--number N] [--timestamp] <feature_description>"
    )

def _parse_args(argv: list[str], argv0: str) -> Args:
    json_mode = False
    dry_run = False
    allow_existing = False
    short_name = ""
    branch_number = ""
    use_timestamp = False
    rest: list[str] = []

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--json":
            json_mode = True
        elif arg == "--dry-run":
            dry_run = True
        elif arg == "--allow-existing-branch":
            allow_existing = True
        elif arg in {"--short-name", "--number"}:
            if i + 1 >= len(argv) or argv[i + 1].startswith("--"):
                print(f"Error: {arg} requires a value", file=sys.stderr)
                raise SystemExit(1)
            i += 1
            if arg == "--short-name":
                short_name = argv[i]
            else:
                branch_number = argv[i]
        elif arg == "--timestamp":
            use_timestamp = True
        elif arg in {"--help", "-h"}:
            sys.stdout.write(_help_text(argv0))
            raise SystemExit(0)
        else:
            rest.append(arg)
        i += 1

    description = " ".join(rest).strip()
    if not description:
        if rest:
            print(
                "Error: Feature description cannot be empty or contain only whitespace",
                file=sys.stderr,
            )
        else:
            print(_usage(argv0), file=sys.stderr)
        raise SystemExit(1)

    return Args(
        json_mode=json_mode,
        dry_run=dry_run,
        allow_existing=allow_existing,
        short_name=short_name,
        branch_number=branch_number,
        use_timestamp=use_timestamp,
        description=description,
    )

def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("template_name")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args(argv)

    repo_root = get_repo_root(Path(__file__))
    try:
        content = resolve_template_content(args.template_name, repo_root)
    except TemplateResolutionError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1
    if content is None:
        print(
            f"ERROR: Could not resolve required {args.template_name} from template stack",
            file=sys.stderr,
        )
        return 1

    if args.json:
        print(
            json.dumps(
                {
                    "TEMPLATE_NAME": args.template_name,
                    "TEMPLATE_CONTENT": content,
                },
                ensure_ascii=False,
                separators=(",", ":"),
            )
        )
    else:
        sys.stdout.write(content)
    return 0

def main(argv: list[str] | None = None) -> int:
    args = list(argv if argv is not None else sys.argv[1:])
    json_mode = False
    for arg in args:
        if arg == "--json":
            json_mode = True
        elif arg in {"--help", "-h"}:
            sys.stdout.write(_help_text(sys.argv[0]))
            return 0

    try:
        paths = get_feature_paths(script_file=Path(__file__))
    except SystemExit as exc:
        if exc.code == 0:
            return 0
        print("ERROR: Failed to resolve feature paths", file=sys.stderr)
        return int(exc.code) if isinstance(exc.code, int) else 1

    paths.feature_dir.mkdir(parents=True, exist_ok=True)

    if paths.impl_plan.is_file():
        if not json_mode:
            print(f"Plan already exists at {paths.impl_plan}, skipping template copy")
    else:
        try:
            template_content = resolve_template_content("plan-template", paths.repo_root)
        except TemplateResolutionError as exc:
            print(f"Error: {exc}", file=sys.stderr)
            return 1
        if template_content is not None:
            paths.impl_plan.write_bytes(template_content.encode("utf-8"))
            if not json_mode:
                print(f"Copied plan template to {paths.impl_plan}")
        else:
            if not json_mode:
                print("Warning: Plan template not found")
            paths.impl_plan.touch()

    if json_mode:
        sys.stdout.write(
            _json_line(
                {
                    "FEATURE_SPEC": str(paths.feature_spec),
                    "IMPL_PLAN": str(paths.impl_plan),
                    "SPECS_DIR": str(paths.feature_dir),
                    "BRANCH": paths.current_branch,
                }
            )
        )
    else:
        print(f"FEATURE_SPEC: {paths.feature_spec}")
        print(f"IMPL_PLAN: {paths.impl_plan}")
        print(f"SPECS_DIR: {paths.feature_dir}")
        print(f"BRANCH: {paths.current_branch}")
    return 0

def _dir_has_entries(path: Path) -> bool:
    try:
        return path.is_dir() and any(path.iterdir())
    except OSError:
        return False

def _available_docs(paths: FeaturePaths) -> list[str]:
    docs: list[str] = []
    if paths.research.is_file():
        docs.append("research.md")
    if paths.data_model.is_file():
        docs.append("data-model.md")
    if _dir_has_entries(paths.contracts_dir):
        docs.append("contracts/")
    if paths.quickstart.is_file():
